window.L5R_CHARACTER = {"slug":"isawa-yukiko","name":"Isawa Yukiko","clan":"Phoenix","family":"Isawa","school":"Ishiken Initiate School","role":"Sage","bucket":"Ishiken","campaign":null,"accent":null,"portrait":"src/portraits/isawa-yukiko.png","concept":null,"summary":null,"tier_count":3,"xp_min":44,"xp_max":98,"twenty_questions":{"template":"core","generated":true,"steps":{"step1":{"answers":{"clan":"Phoenix","ring":"void","skill":"theology","social_status":30},"picks":{}},"step2":{"answers":{"family":"Isawa","ring":"fire","skill1":"meditation","skill2":"theology","wealth":3,"social_glory":39},"picks":{}},"step3":{"answers":{"school":"Ishiken Initiate SchoolSage","roles":"Sage","ring1":"void","ring2":"water","skill1":"fitness","skill2":"sentiment","skill3":"meditation","social_honor":30},"picks":{"techniques":["Sight beyond Existence","Divination","All in Jest"],"school_ability":["Way of the Void"],"equipment":["Sanctified Robes","Wakizashi","Bō","Scroll satchel","Traveling pack"]}},"step4":{"answers":{"stand_out":"While everyone around her recognizes Yukiko as a prodigy, she herself is grounded and practical, treating her intuitive grasp of the elements and the void matter-of-factly and unworthy of comment.","ring":"earth"},"picks":{}},"step5":{"answers":{"social_giri":"To fulfill her role as the reincarnated Little Teacher, with all the baggage and expectations that comes with that."},"picks":{}},"step6":{"answers":{"social_ninjo":"To be allowed to just be a child—to play, to make mistakes, to eat sweets without it being a \"lesson,\" to not carry the weight of destiny for just one day."},"picks":{}},"step7":{"answers":{"clan_relations":"Yukiko sees Righteousness as being what each situation demands; the idea of firm rules for morality are non-sensical to her.","skill":"aesthetics","social_add_glory":0},"picks":{}},"step8":{"answers":{"bushido":"There is honor in every station under the heavens.","skill":"labor","social_add_honor":0,"tenet_paramount":"Compassion","tenet_less_significant":"Righteousness"},"picks":{}},"step9":{"answers":{"success":"At age six Yukiko performed the \"Sight Beyond Existence\" inversion for the first time. She did it without difficulty, and explained the method to the astonished shugenja that observed her in terms that appeared to be quoting the Little Teacher; something she was unfamiliar with. It was this action that saw her adopted into the Isawa and formally intitiated in the ishiken school."},"picks":{}},"step10":{"answers":{"difficulty":"She was a foundling, and was raised by a woman named Tomoe in a small river village. Tomoe found Yukiko's mannerisms and pronouncements strange but charming. This humble upbringing gave Yukiko a grounded perspective that clashes with Phoenix clan expectations. She doesn't understand why people make such a fuss over her abilities, speaks too casually with superiors, and has peasant habits (like eating with her hands or preferring to sit on the floor) that horrify the clan's more traditionalist members. Some Phoenix nobles see her common upbringing as a stain on her destiny, though Yukiko only remembers Tomoe's kindness and doesn't understand why anyone cares."},"picks":{}},"step11":{"answers":{"calms":"What truly brings Yukiko joy is the simple act of giving—whether it's sharing her taiyaki with younger students, using her void sight to help someone find a lost item, or teaching others what comes so naturally to her. She doesn't see her gifts as something to hoard or leverage for status; she genuinely wants to help people and feels happiest when she can make someone else's burden lighter. This manifests in both grand gestures (once she spent weeks helping a lesser shugenja understand a technique they struggled with) and tiny ones (she anonymously leaves small paper cranes she's folded in places where sad people sit). Her generosity is so instinctive that she's often confused when people react with suspicion or try to repay her—in her mind, having more than you need means you should share."},"picks":{}},"step12":{"answers":{"worries":"Despite being constantly surrounded by teachers, minders, and observers, Yukiko is profoundly lonely. Other children are frightened by her abilities or resentful of the attention she receives. Adults treat her either as a sacred relic to be preserved or a phenomenon to be studied—never as a person. She has her doll Hana, but Hana doesn't talk back. She has memories from her past life, but those belong to someone else. Sometimes, late at night, she cries silently because she can't remember the last time someone just... talked to her. Just talked, the way Tomoe used to, about nothing important. This loneliness makes her desperately attached to the few people who show her genuine warmth, and terrified of losing them."},"picks":{}},"step13":{"answers":{"most_learn":"When Isawa Ujina adopted her, it was mostly to provide safety and structure, and the power of the Isawa family and the Phoenix clan. But custody of Yukiko was immediately handed over to Gensho, an abbot from the Brotherhood of Shinsei. He treated Yukiko as a peer, helping her learn but also holding her accountable."},"picks":{}},"step14":{"answers":{"first_sight":"Yukiko's eyes are grey, and at moments will flash entirely white."},"picks":{}},"step15":{"answers":{"stress":"When she is under extreme stress, she will seem to dissociate. At times she will speak, but with words seemingly not her own. She often does not recall what was said during these moments."},"picks":{}},"step16":{"answers":{"relations":"Isawa Ujina - Her formal adoptive father; views her as his duty and legacy, though they have little personal warmth between them. He provided a finger of jade to assist with spiritual protection.\nAbbot Gensho - Her true mentor and guardian from the Brotherhood of Shinsei; treats her as a person first, prodigy second.\nTomoe - The peasant woman who raised her from infancy to age six; Yukiko still loves her and doesn't understand why she can't visit."},"picks":{"item":["Finger of Jade"]}},"step17":{"answers":{"parents_pov":"Tomoe saw past the eerie pronouncements to the little girl who needed bedtime stories and who cried when birds fell from their nests. When the Isawa family came to claim Yukiko after her demonstration of void techniques, Tomoe wept but didn't fight it—she'd always known the child was destined for something beyond a river village. She still prays to the Fortunes that someone, somewhere, is making sure her little Yuki-chan is eating properly.","skill":"games"},"picks":{}},"step18":{"answers":{"heritage_name":"Yukiko was written on the bundle that was found with the baby; the provenance of the name is unknown.","heritage_1":3,"heritage_2":8,"heritage_add_honor":0,"heritage_add_glory":5,"heritage_add_status":0,"skill":"design"},"picks":{}},"step19":{"answers":{"firstname":"Yukiko"},"picks":{}},"step20":{"answers":{"death":"Yukiko doesn't concern herself with death. She just hopes that, in the next life, she was go a little longer before discovery."},"picks":{}}}},"notes":"","curriculum":[{"rank":1,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Meditation","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Skulduggery","prereq":false},{"rank":1,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1 Air Invocations","prereq":true},{"rank":1,"kind":"Tech. Grp.","group":"inversion","label":"Rank 1 Inversions","prereq":false},{"rank":1,"kind":"Technique","group":"ritual","label":"Tea Ceremony","prereq":true},{"rank":2,"kind":"Skill Group","group":null,"label":"Martial Skills","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Command","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Composition","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":2,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1-2 Fire Invocations","prereq":true},{"rank":2,"kind":"Tech. Grp.","group":"inversion","label":"Rank 1-2 Inversions","prereq":false},{"rank":2,"kind":"Technique","group":"shuji","label":"All Arts Are One","prereq":true},{"rank":3,"kind":"Skill Group","group":null,"label":"Social Skills","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Government","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Meditation","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":3,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1-3 Water Invocations","prereq":true},{"rank":3,"kind":"Tech. Grp.","group":"inversion","label":"Rank 1-3 Inversions","prereq":false},{"rank":3,"kind":"Technique","group":"shuji","label":"A Samurai’s Fate","prereq":true},{"rank":4,"kind":"Skill Group","group":null,"label":"Trade Skills","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Meditation","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Theology","prereq":false},{"rank":4,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1-4 Earth Invocations","prereq":true},{"rank":4,"kind":"Tech. Grp.","group":"inversion","label":"Rank 1-4 Inversions","prereq":false},{"rank":4,"kind":"Technique","group":"shuji","label":"The Immovable Hand of Peace","prereq":true},{"rank":5,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Meditation","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Survival","prereq":false},{"rank":5,"kind":"Tech. Grp.","group":"invocation","label":"Rank 1-5 Invocations","prereq":true},{"rank":5,"kind":"Tech. Grp.","group":"inversion","label":"Rank 1-5 Inversions","prereq":false},{"rank":5,"kind":"Technique","group":"shuji","label":"Rouse the Soul","prereq":false}],"tiers":[{"xp":44,"label":"Awakened Soul","rank":1,"school":"Ishiken Initiate School","foundry_id":"uddhC4czlnyZAYjJ","rings":{"air":1,"earth":2,"fire":2,"water":2,"void":3},"skills":{"artisan":{"aesthetics":1,"composition":0,"design":1,"smithing":0},"martial":{"fitness":1,"melee":0,"ranged":0,"unarmed":0,"meditation":5,"tactics":0},"scholar":{"culture":0,"government":0,"medicine":0,"sentiment":2,"theology":3},"social":{"command":1,"courtesy":1,"games":1,"performance":0},"trade":{"commerce":0,"labor":1,"seafaring":0,"skulduggery":0,"survival":0}},"social":{"honor":30,"glory":44,"status":30,"ninjo":"To be allowed to just be a child—to play, to make mistakes, to eat sweets without it being a \"lesson,\" to not carry the weight of destiny for just one day.","giri":"To fulfill her role as the reincarnated Little Teacher, with all the baggage and expectations that comes with that.","bushido_tenets":{"paramount":"Compassion","less_significant":"Righteousness"}},"derived":{"endurance":8,"composure":8,"focus":3,"vigilance":2,"void_points":3},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[],"techniques":[{"name":"Sight beyond Existence","xp_used":0,"xp_cost":6,"in_curriculum":false,"bought_at_rank":0,"kind":"inversion","rank":1,"description":"<p><em>The Void is nonexistence; therefore, within it, all possibilities exist. One who attunes their senses to nonexistence can perceive the other possible realities that ripple outward from each moment of action. The signs often do not come as complete visions, but as brief flashes: hazy vignettes of a world that never was. The rustling of leaves from a tree that has not yet grown, the first laugh shared with a new friend, the scent of blood and burning flesh. However, these rippling potential truths can become intoxicating, drawing an undisciplined mind deeper and deeper into twisted realms of refracted possibility until there is no escape. This is what those who study the Void call the “Lying Darkness”: the trap that awaits all who let their worldly desires guide their ventures into the Void.</em></p><p><strong>Activation:</strong> Once per session, immediately after you or another character at range 0–3 performs an action or makes a choice of great consequence in a narrative scene, you may make a TN 2 Theology (void) check targeting that character to peer beyond the lie of time and find another outcome.</p><p><strong>Effects:</strong> If you succeed, you scry for another outcome and return to the moment before the action was performed. All effects and outcomes stemming from the action are undone, but only you and the target are aware of the reality that no longer is. If you are the target, you may choose the same or a different action or decision. If another character is the target, you may say up to five words to the target before they act or make a decision.</p><h4>New Opportunities</h4><p>(op): If you target another character and you succeed, you may perform an action immediately before the target performs their new action.</p><h4>Magnitude</h4><p><strong>Magnitude 1+:</strong> You see one possible consequence of the original action or decision that would occur before the end of the scene.</p><p><strong>Magnitude 2+:</strong> You see one additional possible consequence of the original action or decision that would occur in the next year.</p><p><strong>Magnitude 3+:</strong> You see one additional possible consequence of the original action or decision that would occur in the next decades, or even further in the future.</p>","source":{"book":"celestial_realms","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-inversions-l5r-sortilege.Item.2AUf2kuJdMWvY13L","skill":"theology"},{"name":"Divination","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<p><span class=\"fontstyle0\">The ritualist peers into a character’s future, ascertaining their fate from the patterns of the stars, the char marks upon animal bones, the placement of cast shells, or other omens they can read.</span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 2 Theology (void) check </span><span class=\"fontstyle3\">targeting one character to see glimpses of their future.</span></p><p><span class=\"fontstyle0\"><strong>Effects:</strong> </span><span class=\"fontstyle2\">If you succeed, choose one of the following omens that you see in the target’s near future:</span></p><ul><li><p><span class=\"fontstyle0\">- Omen of the Azure Dragon: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Artisan skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Black Tortoise: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Scholar skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the White Tiger: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Martial skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Vermilion Bird: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Social skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Weaver and the Cowherd: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Trade skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li></ul><p><span class=\"fontstyle2\">If you fail, the GM chooses one of the above omens instead. The target cannot receive another divination until the next game session.</span></p><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle0\">: </span><span class=\"fontstyle2\">If you fail, an additional omen appears to you after the first. Choose one of the above omens in addition to the one the GM chose.</span></p>","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.JUOu5wKW90qDj9BG","skill":"theology"},{"name":"All in Jest","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Veteran courtiers sometimes play off missteps as jokes. This underhanded but effective tactic puts the other person in a difficult position: press the issue and seem stubborn, or let it slide and give the courtier a pass.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Commerce (water), Courtesy (water), or Performance (water) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(water)(op)+: </span><span class=\"fontstyle3\">If you forfeited honor as part of the check in order to say something rude or appeal to your target’s base desires (greed, lust, laziness, etc.), regain 1 honor per (op) spent this way (see </span><span class=\"fontstyle2\">Forfeiting Social Attributes</span><span class=\"fontstyle3\">, on page 37).</span></p>","source":{"book":"core_rulebook","page":220},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.vzyZwVERv5Q2kulT","skill":"commerce,courtesy,performance"},{"name":"Way of the Void","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When you make a check using your Void Ring, after rolling dice, you may receive a number of fatigue up to your school rank. If you do, you may </span><span class=\"fontstyle2\"><strong>pull</strong> </span><span class=\"fontstyle0\">or </span><span class=\"fontstyle2\"><strong>push</strong></span><span class=\"fontstyle0\">: </span></p><p><span class=\"fontstyle0\">If you </span><span class=\"fontstyle2\"><strong>pull</strong></span><span class=\"fontstyle0\">, choose a number of dice with non-blank results equal to the fatigue you received, and alter each to a blank result.</span></p><p><span class=\"fontstyle0\">If you </span><span class=\"fontstyle2\"><strong>push</strong></span><span class=\"fontstyle0\">, choose a number of dice with blank results equal to the fatigue you received, and alter each to a non-blank result of your choice.</span> </p>","source":{"book":"celestial_realms","page":82},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.fwNLwyKgWpWlq9nd"},{"name":"Wisdom of Countless Lifetimes","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When making a skill check, you may spend 1 Void point to treat your skill rank as 1 higher, to a maximum of 6. If you fail the check, gain 1 Void point.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.1jgC3c1A3Dkvpb6k"}],"peculiarities":[{"name":"Portentous Birth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>The childbirth assistant carried the silent bundle to the priest outside of the birthing chamber. The child’s grandmother followed with a stony look on her face.</em></span></p><p><span class=\"fontstyle2\"><em>Why isn’t the child crying? </em></span><span class=\"fontstyle0\"><em>the priest thought.</em></span></p><p><span class=\"fontstyle0\"><em>“Show him,” the grandmother said.</em></span></p><p><span class=\"fontstyle0\"><em>The assistant carefully unwrapped the bundle. The unnerving infant stared about, clear-eyed, as the grandmother pointed out the seven moles in a perfect circle on their ear.</em></span></p><p><span class=\"fontstyle0\"><em>“The child will reverse the family’s bad fortune!” the priest exclaimed. The grandmother let out a breath and smiled for the first time in years.</em></span></p><p></p><p><span class=\"fontstyle2\">The following apply to a character with the Portentous Birth distinction:</span></p><ul><li><p><span class=\"fontstyle2\">- You are known among your clan or family group to have been born under blessed circumstances or have had some sort of mark or other indication of greatness bestowed upon you by the Heavens. When you interact with someone who knows of your portentous birth and believes in its power, they treat you favorably and may be inclined to give you special privileges as long as you do not give them a reason to treat you otherwise.</span></p></li><li><p><span class=\"fontstyle2\">- When performing a check for which your fortuitous birth is an asset (such as a Composition (fire) check to craft a clever request to someone who believes in the legacy of your birth or a Theology (fire) check to theorize about an omen), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"celestial_realms","page":89},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.US7uSaPQHxj4wCKy"},{"name":"Adopted Peasant","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"fire","types":"Interpersonal","description":"<p><em>Even though she sat with the rest of her adopted family, she had never felt so invisible.</em></p><p><em>“This is why we sweep the shrine of dirt. Any foreign intrusion violates its sanctity,” her brother said.</em></p><p><em>Takako bowed her head ever so slightly. “Yes, but priests also sprinkle salt in the corners. So a foreign intrusion can sometimes strengthen its purity.”</em></p><p><em>Her brother tensed up. The rest of her family refused to look at her. This transgression will not be forgotten.</em></p><p></p><p>The following apply to a character with the Adopted Peasant adversity:</p><ul><li><p>- Although adopted by a samurai family, you were born a peasant. Other samurai who know this fact are likely to look down upon you and may use this fact against you socially.</p></li><li><p>- When you make a check to deal authoritatively or collegially with a samurai who knows of your peasant birth (such as a Command (fire) check to give an order to a subordinate or a Courtesy (fire) check to impugn another’s honor), you must choose and reroll two dice showing (su) or (ex) results. After resolving the check, if you failed, you regain 1 Void point.</p></li></ul>","source":{"book":"emerald_empire","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.2bPrBcyXEsRvGPnn"},{"name":"Generosity","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Interpersonal","description":"<p><span class=\"fontstyle0\"><em>During the sixth month of the year after the biannual collection of taxes, the city of Ryokō Owari Toshi celebrates the Days of Generosity. As the festival begins, the head priest of the local temple draws a name in a lottery. The person whose name is drawn becomes “King of Generosity” and “rules” over the festival.</em></span></p><p><span class=\"fontstyle0\"><em>The festival is marked by gift giving and drunkenness. The festival king decides who the best gift giver is on each of the celebration’s three days. That person receives a portion of the “king’s purse,” a collection of coins given to the festival king to pay him for blessing the giver with a prosperous year ahead.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Generosity passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You can always identify a proper gift for a particular person that does not risk giving offense or slighting them publicly.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to acquire or give a gift (such as a Design (water) check to select an item that complements someone’s wardrobe or a Commerce (water) check to find and select a gift at a market), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.bvb90GLa9nJkkUun"},{"name":"Loneliness","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"void","types":"Interpersonal, Mental","description":"<p><em>A stalk of barley,<br>Plucked by a starving farmer,<br>Quickly forgotten.</em></p><p><strong>Effects:</strong> The following apply to a character with the Loneliness anxiety:</p><ul><li><p>- You derive energy and pleasure from social interactions, and being alone makes you uncomfortable or morose. You look for excuses to avoid being alone and find it difficult to turn down any social engagement.</p></li><li><p>- After performing a check that requires you to be alone (such as a Composition (void) check to write a letter declining an invitation to the theater or a Meditation (void) check to spend a prolonged time in dedicated introspection), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"emerald_empire","page":248},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.yc64FF9SMsQEjs4R"},{"name":"Support of Brotherhood of Shinsei","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Interpersonal","custom":true,"description":"<p><span class=\"fontstyle0\"><em>Akodo Emi avoided the rōnin’s stroke narrowly, sweeping at his feet to gain distance. He was good, yet she could beat him. But not quickly, and time was her true enemy tonight.</em></span></p><p><span class=\"fontstyle0\"><em>Suddenly, a hail of slingstones clattered across the ground near the rōnin’s feet. Down the street rushed several figures wearing the Mon of the Sparrow.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Support of [One Group] distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You have proven yourself to a particular group, which is willing to help you when doing so will not damage its reputation. Its members will offer you their hospitality, including meals, a place to rest, and medical attention if they have a healer. They will also grant you access to their other facilities, such as libraries, smithies, or stables. Confer with the GM to select a campaign-appropriate group when choosing this advantage.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check to interact with the members of the chosen group that relies on your rapport (such as a Command (water) check to issue them orders or a Performance (water) check to cause an audience of them to desire something), you may reroll up to two dice.</span></p></li></ul>","source_reference":{"source":"core_rulebook","page":110}}],"titles":[{"name":"Awakened Soul","xp_used":44,"xp_cost":44,"in_curriculum":false,"bought_at_rank":1,"description":"<p><span class=\"fontstyle0\">Most Rokugani believe in reincarnation, the passage of the soul into a new form after the death of the body. Shinseism in particular emphasizes the importance of reincarnation and the role it plays within the cosmology, but even among those who favor other religious traditions, few argue that existence ends at death. While the specifics of how and why reincarnation occurs vary by doctrine, most religious accounts agree that memory is erased upon death, in the afterlife, or during the process of the return to life.</span></p><p><span class=\"fontstyle0\">Yet some things can persist even across lifetimes. Some people are capable of connecting with the lives of past people, entities, and existences as an extension of their own being - beings that by all account seem to be their past lives. The Togashi Tattooed Order is one organization dedicated to those who again and again reincarnate and seek a particular destiny, but other spiritualists claim to have memories of their past lives as well, and the phenomenon can occur within individuals unrelated to any religious group.</span></p><p><span class=\"fontstyle0\">Memories of one's past lives generally begin murky, but may become clearer in physical proximity to individuals, artifacts, or places important to those beings. These visions and senses can be terrifying and disorienting at first, but when they occur, it is often of vital importance to both past and present self. Indeed, some work cannot be completed in a single lifetime.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">The GM. Even more than usual, this title is only available if it is narratively appropriate to the campaign.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+0</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Wisdom of Countless Lifetimes</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Social Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Scholar Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Culture</p></td><td><p>Skill</p></td></tr><tr><td><p>Meditation</p></td><td><p>Skill</p></td></tr><tr><td><p>Survival</p></td><td><p>Skill</p></td></tr><tr><td><p>Theology</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-kiho.Item.L5RCoreKih000038\" data-pack=\"l5r5e.core-techniques-kiho\" data-type=\"Item\" data-id=\"L5RCoreKih000038\">(kiho) Eternal Mind’s Gate</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-rituals.Item.L5RCoreRit000035\" data-pack=\"l5r5e.core-techniques-rituals\" data-type=\"Item\" data-id=\"L5RCoreRit000035\">(ritual) Trance of Lives Past</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"writ_of_the_wild","page":142},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.lwnOHnIHVy5M9wUb"}],"bonds":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Bō","quantity":1,"description":"<p><span class=\"fontstyle0\">The bō, a humble staff, is a versatile weapon found throughout Rokugan. Roughly six feet long and made from sturdy hardwood, it is carried by travelers who need both a walking stick and an inconspicuous weapon.</span></p>","source":{"book":"core_rulebook","page":235},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.0ZcXEpZP8WC9KVUv","damage":6,"deadliness":2,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Polearms","rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p><span class=\"fontstyle0\">The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called </span><span class=\"fontstyle2\">jōe </span><span class=\"fontstyle0\">(literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Scroll satchel","quantity":1,"description":"","source":{"book":"core_rulebook","page":60},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.DhMU7Z6UsxB7CSvR","rarity":"3","zeni":"1 bu"},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Hana [Doll]","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Finger of Jade","quantity":1,"description":"<p>A finger of jade is a length of the precious green stone worn about the neck on a thong to ward off the corrupting effects of the Taint. Bit by bit, the finger of jade is consumed by this process. (Cost: 1 koku. Rarity: 6. Qualities: Sacred.)</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.DPc5XLaPHWGkcNs5","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000014","name":"Sacred"}]}]},{"xp":74,"label":"Awakened Soul, Rank 2","rank":2,"school":"Ishiken Initiate School","foundry_id":"o6nJImFmnkUzcWPZ","rings":{"air":2,"earth":2,"fire":2,"water":2,"void":4},"skills":{"artisan":{"aesthetics":1,"composition":0,"design":1,"smithing":0},"martial":{"fitness":1,"melee":0,"ranged":0,"unarmed":0,"meditation":5,"tactics":0},"scholar":{"culture":0,"government":0,"medicine":0,"sentiment":2,"theology":3},"social":{"command":1,"courtesy":1,"games":1,"performance":0},"trade":{"commerce":0,"labor":1,"seafaring":0,"skulduggery":0,"survival":0}},"social":{"honor":30,"glory":44,"status":30,"ninjo":"To be allowed to just be a child—to play, to make mistakes, to eat sweets without it being a \"lesson,\" to not carry the weight of destiny for just one day.","giri":"To fulfill her role as the reincarnated Little Teacher, with all the baggage and expectations that comes with that.","bushido_tenets":{"paramount":"Compassion","less_significant":"Righteousness"}},"derived":{"endurance":8,"composure":8,"focus":4,"vigilance":2,"void_points":4},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Air +1 (1 -> 2)","type":"ring","skill":null,"ring":"air","at_rank":1,"xp":6,"in_curriculum":false},{"label":"Void +1 (3 -> 4)","type":"ring","skill":null,"ring":"void","at_rank":1,"xp":12,"in_curriculum":false}],"techniques":[{"name":"Sight beyond Existence","xp_used":0,"xp_cost":6,"in_curriculum":false,"bought_at_rank":0,"kind":"inversion","rank":1,"description":"<p><em>The Void is nonexistence; therefore, within it, all possibilities exist. One who attunes their senses to nonexistence can perceive the other possible realities that ripple outward from each moment of action. The signs often do not come as complete visions, but as brief flashes: hazy vignettes of a world that never was. The rustling of leaves from a tree that has not yet grown, the first laugh shared with a new friend, the scent of blood and burning flesh. However, these rippling potential truths can become intoxicating, drawing an undisciplined mind deeper and deeper into twisted realms of refracted possibility until there is no escape. This is what those who study the Void call the “Lying Darkness”: the trap that awaits all who let their worldly desires guide their ventures into the Void.</em></p><p><strong>Activation:</strong> Once per session, immediately after you or another character at range 0–3 performs an action or makes a choice of great consequence in a narrative scene, you may make a TN 2 Theology (void) check targeting that character to peer beyond the lie of time and find another outcome.</p><p><strong>Effects:</strong> If you succeed, you scry for another outcome and return to the moment before the action was performed. All effects and outcomes stemming from the action are undone, but only you and the target are aware of the reality that no longer is. If you are the target, you may choose the same or a different action or decision. If another character is the target, you may say up to five words to the target before they act or make a decision.</p><h4>New Opportunities</h4><p>(op): If you target another character and you succeed, you may perform an action immediately before the target performs their new action.</p><h4>Magnitude</h4><p><strong>Magnitude 1+:</strong> You see one possible consequence of the original action or decision that would occur before the end of the scene.</p><p><strong>Magnitude 2+:</strong> You see one additional possible consequence of the original action or decision that would occur in the next year.</p><p><strong>Magnitude 3+:</strong> You see one additional possible consequence of the original action or decision that would occur in the next decades, or even further in the future.</p>","source":{"book":"celestial_realms","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-inversions-l5r-sortilege.Item.2AUf2kuJdMWvY13L","skill":"theology"},{"name":"Divination","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<p><span class=\"fontstyle0\">The ritualist peers into a character’s future, ascertaining their fate from the patterns of the stars, the char marks upon animal bones, the placement of cast shells, or other omens they can read.</span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 2 Theology (void) check </span><span class=\"fontstyle3\">targeting one character to see glimpses of their future.</span></p><p><span class=\"fontstyle0\"><strong>Effects:</strong> </span><span class=\"fontstyle2\">If you succeed, choose one of the following omens that you see in the target’s near future:</span></p><ul><li><p><span class=\"fontstyle0\">- Omen of the Azure Dragon: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Artisan skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Black Tortoise: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Scholar skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the White Tiger: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Martial skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Vermilion Bird: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Social skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Weaver and the Cowherd: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Trade skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li></ul><p><span class=\"fontstyle2\">If you fail, the GM chooses one of the above omens instead. The target cannot receive another divination until the next game session.</span></p><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle0\">: </span><span class=\"fontstyle2\">If you fail, an additional omen appears to you after the first. Choose one of the above omens in addition to the one the GM chose.</span></p>","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.JUOu5wKW90qDj9BG","skill":"theology"},{"name":"All in Jest","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Veteran courtiers sometimes play off missteps as jokes. This underhanded but effective tactic puts the other person in a difficult position: press the issue and seem stubborn, or let it slide and give the courtier a pass.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Commerce (water), Courtesy (water), or Performance (water) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(water)(op)+: </span><span class=\"fontstyle3\">If you forfeited honor as part of the check in order to say something rude or appeal to your target’s base desires (greed, lust, laziness, etc.), regain 1 honor per (op) spent this way (see </span><span class=\"fontstyle2\">Forfeiting Social Attributes</span><span class=\"fontstyle3\">, on page 37).</span></p>","source":{"book":"core_rulebook","page":220},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.vzyZwVERv5Q2kulT","skill":"commerce,courtesy,performance"},{"name":"Way of the Void","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When you make a check using your Void Ring, after rolling dice, you may receive a number of fatigue up to your school rank. If you do, you may </span><span class=\"fontstyle2\"><strong>pull</strong> </span><span class=\"fontstyle0\">or </span><span class=\"fontstyle2\"><strong>push</strong></span><span class=\"fontstyle0\">: </span></p><p><span class=\"fontstyle0\">If you </span><span class=\"fontstyle2\"><strong>pull</strong></span><span class=\"fontstyle0\">, choose a number of dice with non-blank results equal to the fatigue you received, and alter each to a blank result.</span></p><p><span class=\"fontstyle0\">If you </span><span class=\"fontstyle2\"><strong>push</strong></span><span class=\"fontstyle0\">, choose a number of dice with blank results equal to the fatigue you received, and alter each to a non-blank result of your choice.</span> </p>","source":{"book":"celestial_realms","page":82},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.fwNLwyKgWpWlq9nd"},{"name":"Wisdom of Countless Lifetimes","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When making a skill check, you may spend 1 Void point to treat your skill rank as 1 higher, to a maximum of 6. If you fail the check, gain 1 Void point.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.1jgC3c1A3Dkvpb6k"},{"name":"One Within the Void","xp_used":6,"xp_cost":6,"in_curriculum":true,"bought_at_rank":1,"kind":"inversion","rank":1,"description":"<p><em>Within the emptiness of the Void, the divisions between “self” and “other” become as mutable as any other barriers that seem absolute within reality. Those trained to wield the Void can share their expertise, tendencies, and even emotional states with other beings, allowing them to act with uncanny coordination.</em></p><p><strong>Activation:</strong> As a Support action, you may make a TN 2 Sentiment (void) check targeting yourself and one other character at range 0–3.</p><p><strong>Effects:</strong> If you succeed, you augment all targets with the ability to communicate with each other without words, making their intentions clear even if they do not speak the same language. When any target makes a check, one other target may receive 2 fatigue to provide assistance on the check regardless of distance. This effect lasts until the end of the scene.</p><h4>New Opportunities</h4><p>(op)+: Choose one additional target per (op) spent this way.</p><h4>Magnitude</h4><p><strong>Magnitude 1+:</strong> When a target is dealt strife, one other target of your choice may receive that strife instead.</p><p><strong>Magnitude 3+:</strong> Choose a ring or skill. When any target makes a check using that ring or skill, they may use any other target’s rank in that ring or skill instead of their own.</p>","source":{"book":"celestial_realms","page":114},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-inversions-l5r-sortilege.Item.0XWS8RHp15XFc5Ji","skill":"sentiment"},{"name":"Nature’s Touch","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"invocation","rank":1,"description":"<p>Shinjo's Whispers (Ancestral), Run Alongside the Ki-Rin (Fortunist), Voice of the Glen King (Foreign)</p><p><em>To perform this rite, the shugenja seeks Chikushō-dō, the Realm of Animals, in the world around them and in their own heart. This allows the shugenja to communicate with (though not dominate) animals of the mortal realm.</em></p><p><strong>Activation:</strong> As a Support action, you may make a TN 1 Theology (air) check targeting yourself.</p><p><strong>Effects:</strong> If you succeed, you augment yourself with the ability to speak to animals of the natural world (but not Otherworldly or Tainted beings). Animals can understand you (within their ability to do so, naturally—human political relationships will have no meaning to horses, no matter how many times you explain them). They are not compelled to obey you, however. This effect persists until the end of the scene.</p><h4>New Opportunities</h4><p>(air)(op): Until the end of the scene, you can understand animals’ speech.</p><p>(air)(op): If you succeed, the animal also acts favorably toward you automatically due to your politeness, fulfilling one request that does not put it in danger without having to be convinced with bribes of food or subsequent checks.</p><p>(air)(op)(op): If you succeed, you can communicate with an Otherworldly being this way, provided it has anything to say to you.</p>","source":{"book":"core_rulebook","page":194},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.RGv4DW5lszwSVJiy","skill":"theology"},{"name":"Tea Ceremony","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ritual","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When Lady Doji served tea for the very first Emperor, the tea ceremony was born. Ceremony styles vary among the clans, from the gilded tea rooms of the Phoenix to the imperfect tea bowls of the Dragon, the early morning gatherings of the Crane to the snow- and moon-viewing ceremonies of the Scorpion. However, at its core the tea ceremony is fundamentally an appreciation of tea and, if done well, a spiritual moment for its participants. The tea represents all five elements: the fire used to heat the water, the earth from which the tea is grown, and the air that carries the aroma of the tea. Finally, void holds all four elements together, and brings in the mysterious fifth element, the moment of harmony and tranquility as one sips the tea.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per game session, as a downtime activity using a tea set, you may make a </span><span class=\"fontstyle2\">TN 2 Performance (void) check </span><span class=\"fontstyle3\">targeting yourself and a number of other characters up to your ranks in Culture, who are also participants. Up to one other participant may assist, providing the usual benefits (see </span><span class=\"fontstyle2\">Assistance </span><span class=\"fontstyle3\">on page 26).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">Each target removes 3 strife, plus additional strife equal to your bonus successes.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of each target’s next check by 1.</span></p><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle6\">+: </span><span class=\"fontstyle3\">Each target removes 1 fatigue, plus 1 fatigue per (op)</span><span class=\"fontstyle5\">(op) </span><span class=\"fontstyle3\">spent this way.</span></p><p><span class=\"fontstyle5\">(op)(op)</span><span class=\"fontstyle6\">: </span><span class=\"fontstyle3\">If you succeed, each target gains 1 Void point.</span></p>","source":{"book":"core_rulebook","page":213},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.JWmEEgfShNBM4fEK","skill":"performance"}],"peculiarities":[{"name":"Portentous Birth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>The childbirth assistant carried the silent bundle to the priest outside of the birthing chamber. The child’s grandmother followed with a stony look on her face.</em></span></p><p><span class=\"fontstyle2\"><em>Why isn’t the child crying? </em></span><span class=\"fontstyle0\"><em>the priest thought.</em></span></p><p><span class=\"fontstyle0\"><em>“Show him,” the grandmother said.</em></span></p><p><span class=\"fontstyle0\"><em>The assistant carefully unwrapped the bundle. The unnerving infant stared about, clear-eyed, as the grandmother pointed out the seven moles in a perfect circle on their ear.</em></span></p><p><span class=\"fontstyle0\"><em>“The child will reverse the family’s bad fortune!” the priest exclaimed. The grandmother let out a breath and smiled for the first time in years.</em></span></p><p></p><p><span class=\"fontstyle2\">The following apply to a character with the Portentous Birth distinction:</span></p><ul><li><p><span class=\"fontstyle2\">- You are known among your clan or family group to have been born under blessed circumstances or have had some sort of mark or other indication of greatness bestowed upon you by the Heavens. When you interact with someone who knows of your portentous birth and believes in its power, they treat you favorably and may be inclined to give you special privileges as long as you do not give them a reason to treat you otherwise.</span></p></li><li><p><span class=\"fontstyle2\">- When performing a check for which your fortuitous birth is an asset (such as a Composition (fire) check to craft a clever request to someone who believes in the legacy of your birth or a Theology (fire) check to theorize about an omen), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"celestial_realms","page":89},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.US7uSaPQHxj4wCKy"},{"name":"Adopted Peasant","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"fire","types":"Interpersonal","description":"<p><em>Even though she sat with the rest of her adopted family, she had never felt so invisible.</em></p><p><em>“This is why we sweep the shrine of dirt. Any foreign intrusion violates its sanctity,” her brother said.</em></p><p><em>Takako bowed her head ever so slightly. “Yes, but priests also sprinkle salt in the corners. So a foreign intrusion can sometimes strengthen its purity.”</em></p><p><em>Her brother tensed up. The rest of her family refused to look at her. This transgression will not be forgotten.</em></p><p></p><p>The following apply to a character with the Adopted Peasant adversity:</p><ul><li><p>- Although adopted by a samurai family, you were born a peasant. Other samurai who know this fact are likely to look down upon you and may use this fact against you socially.</p></li><li><p>- When you make a check to deal authoritatively or collegially with a samurai who knows of your peasant birth (such as a Command (fire) check to give an order to a subordinate or a Courtesy (fire) check to impugn another’s honor), you must choose and reroll two dice showing (su) or (ex) results. After resolving the check, if you failed, you regain 1 Void point.</p></li></ul>","source":{"book":"emerald_empire","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.2bPrBcyXEsRvGPnn"},{"name":"Generosity","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Interpersonal","description":"<p><span class=\"fontstyle0\"><em>During the sixth month of the year after the biannual collection of taxes, the city of Ryokō Owari Toshi celebrates the Days of Generosity. As the festival begins, the head priest of the local temple draws a name in a lottery. The person whose name is drawn becomes “King of Generosity” and “rules” over the festival.</em></span></p><p><span class=\"fontstyle0\"><em>The festival is marked by gift giving and drunkenness. The festival king decides who the best gift giver is on each of the celebration’s three days. That person receives a portion of the “king’s purse,” a collection of coins given to the festival king to pay him for blessing the giver with a prosperous year ahead.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Generosity passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You can always identify a proper gift for a particular person that does not risk giving offense or slighting them publicly.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to acquire or give a gift (such as a Design (water) check to select an item that complements someone’s wardrobe or a Commerce (water) check to find and select a gift at a market), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.bvb90GLa9nJkkUun"},{"name":"Loneliness","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"void","types":"Interpersonal, Mental","description":"<p><em>A stalk of barley,<br>Plucked by a starving farmer,<br>Quickly forgotten.</em></p><p><strong>Effects:</strong> The following apply to a character with the Loneliness anxiety:</p><ul><li><p>- You derive energy and pleasure from social interactions, and being alone makes you uncomfortable or morose. You look for excuses to avoid being alone and find it difficult to turn down any social engagement.</p></li><li><p>- After performing a check that requires you to be alone (such as a Composition (void) check to write a letter declining an invitation to the theater or a Meditation (void) check to spend a prolonged time in dedicated introspection), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"emerald_empire","page":248},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.yc64FF9SMsQEjs4R"},{"name":"Support of Brotherhood of Shinsei","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Interpersonal","custom":true,"description":"<p><span class=\"fontstyle0\"><em>Akodo Emi avoided the rōnin’s stroke narrowly, sweeping at his feet to gain distance. He was good, yet she could beat him. But not quickly, and time was her true enemy tonight.</em></span></p><p><span class=\"fontstyle0\"><em>Suddenly, a hail of slingstones clattered across the ground near the rōnin’s feet. Down the street rushed several figures wearing the Mon of the Sparrow.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Support of [One Group] distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You have proven yourself to a particular group, which is willing to help you when doing so will not damage its reputation. Its members will offer you their hospitality, including meals, a place to rest, and medical attention if they have a healer. They will also grant you access to their other facilities, such as libraries, smithies, or stables. Confer with the GM to select a campaign-appropriate group when choosing this advantage.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check to interact with the members of the chosen group that relies on your rapport (such as a Command (water) check to issue them orders or a Performance (water) check to cause an audience of them to desire something), you may reroll up to two dice.</span></p></li></ul>","source_reference":{"source":"core_rulebook","page":110}}],"titles":[{"name":"Awakened Soul","xp_used":44,"xp_cost":44,"in_curriculum":false,"bought_at_rank":1,"description":"<p><span class=\"fontstyle0\">Most Rokugani believe in reincarnation, the passage of the soul into a new form after the death of the body. Shinseism in particular emphasizes the importance of reincarnation and the role it plays within the cosmology, but even among those who favor other religious traditions, few argue that existence ends at death. While the specifics of how and why reincarnation occurs vary by doctrine, most religious accounts agree that memory is erased upon death, in the afterlife, or during the process of the return to life.</span></p><p><span class=\"fontstyle0\">Yet some things can persist even across lifetimes. Some people are capable of connecting with the lives of past people, entities, and existences as an extension of their own being - beings that by all account seem to be their past lives. The Togashi Tattooed Order is one organization dedicated to those who again and again reincarnate and seek a particular destiny, but other spiritualists claim to have memories of their past lives as well, and the phenomenon can occur within individuals unrelated to any religious group.</span></p><p><span class=\"fontstyle0\">Memories of one's past lives generally begin murky, but may become clearer in physical proximity to individuals, artifacts, or places important to those beings. These visions and senses can be terrifying and disorienting at first, but when they occur, it is often of vital importance to both past and present self. Indeed, some work cannot be completed in a single lifetime.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">The GM. Even more than usual, this title is only available if it is narratively appropriate to the campaign.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+0</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Wisdom of Countless Lifetimes</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Social Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Scholar Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Culture</p></td><td><p>Skill</p></td></tr><tr><td><p>Meditation</p></td><td><p>Skill</p></td></tr><tr><td><p>Survival</p></td><td><p>Skill</p></td></tr><tr><td><p>Theology</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-kiho.Item.L5RCoreKih000038\" data-pack=\"l5r5e.core-techniques-kiho\" data-type=\"Item\" data-id=\"L5RCoreKih000038\">(kiho) Eternal Mind’s Gate</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-rituals.Item.L5RCoreRit000035\" data-pack=\"l5r5e.core-techniques-rituals\" data-type=\"Item\" data-id=\"L5RCoreRit000035\">(ritual) Trance of Lives Past</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"writ_of_the_wild","page":142},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.lwnOHnIHVy5M9wUb"}],"bonds":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Bō","quantity":1,"description":"<p><span class=\"fontstyle0\">The bō, a humble staff, is a versatile weapon found throughout Rokugan. Roughly six feet long and made from sturdy hardwood, it is carried by travelers who need both a walking stick and an inconspicuous weapon.</span></p>","source":{"book":"core_rulebook","page":235},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.0ZcXEpZP8WC9KVUv","damage":6,"deadliness":2,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Polearms","rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p><span class=\"fontstyle0\">The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called </span><span class=\"fontstyle2\">jōe </span><span class=\"fontstyle0\">(literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Scroll satchel","quantity":1,"description":"","source":{"book":"core_rulebook","page":60},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.DhMU7Z6UsxB7CSvR","rarity":"3","zeni":"1 bu"},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Hana [Doll]","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Finger of Jade","quantity":1,"description":"<p>A finger of jade is a length of the precious green stone worn about the neck on a thong to ward off the corrupting effects of the Taint. Bit by bit, the finger of jade is consumed by this process. (Cost: 1 koku. Rarity: 6. Qualities: Sacred.)</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.DPc5XLaPHWGkcNs5","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000014","name":"Sacred"}]}]},{"xp":98,"label":"Awakened Soul, Rank 3) (Copy","rank":3,"school":"Ishiken Initiate School","foundry_id":"tQeesrhaKZHRa5lB","rings":{"air":2,"earth":2,"fire":2,"water":2,"void":4},"skills":{"artisan":{"aesthetics":1,"composition":1,"design":1,"smithing":0},"martial":{"fitness":1,"melee":0,"ranged":0,"unarmed":0,"meditation":5,"tactics":0},"scholar":{"culture":0,"government":0,"medicine":0,"sentiment":2,"theology":3},"social":{"command":3,"courtesy":1,"games":1,"performance":0},"trade":{"commerce":0,"labor":1,"seafaring":0,"skulduggery":0,"survival":0}},"social":{"honor":30,"glory":44,"status":30,"ninjo":"To be allowed to just be a child—to play, to make mistakes, to eat sweets without it being a \"lesson,\" to not carry the weight of destiny for just one day.","giri":"To fulfill her role as the reincarnated Little Teacher, with all the baggage and expectations that comes with that.","bushido_tenets":{"paramount":"Compassion","less_significant":"Righteousness"}},"derived":{"endurance":8,"composure":8,"focus":4,"vigilance":2,"void_points":4},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Air +1 (1 -> 2)","type":"ring","skill":null,"ring":"air","at_rank":1,"xp":6,"in_curriculum":false},{"label":"Void +1 (3 -> 4)","type":"ring","skill":null,"ring":"void","at_rank":1,"xp":12,"in_curriculum":false},{"label":"Command +1 (1 -> 2)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":4,"in_curriculum":true},{"label":"Composition +1 (0 -> 1)","type":"skill","skill":"composition","ring":"void","at_rank":2,"xp":2,"in_curriculum":true},{"label":"Command +1 (2 -> 3)","type":"skill","skill":"command","ring":"void","at_rank":2,"xp":6,"in_curriculum":true}],"techniques":[{"name":"Sight beyond Existence","xp_used":0,"xp_cost":6,"in_curriculum":false,"bought_at_rank":0,"kind":"inversion","rank":1,"description":"<p><em>The Void is nonexistence; therefore, within it, all possibilities exist. One who attunes their senses to nonexistence can perceive the other possible realities that ripple outward from each moment of action. The signs often do not come as complete visions, but as brief flashes: hazy vignettes of a world that never was. The rustling of leaves from a tree that has not yet grown, the first laugh shared with a new friend, the scent of blood and burning flesh. However, these rippling potential truths can become intoxicating, drawing an undisciplined mind deeper and deeper into twisted realms of refracted possibility until there is no escape. This is what those who study the Void call the “Lying Darkness”: the trap that awaits all who let their worldly desires guide their ventures into the Void.</em></p><p><strong>Activation:</strong> Once per session, immediately after you or another character at range 0–3 performs an action or makes a choice of great consequence in a narrative scene, you may make a TN 2 Theology (void) check targeting that character to peer beyond the lie of time and find another outcome.</p><p><strong>Effects:</strong> If you succeed, you scry for another outcome and return to the moment before the action was performed. All effects and outcomes stemming from the action are undone, but only you and the target are aware of the reality that no longer is. If you are the target, you may choose the same or a different action or decision. If another character is the target, you may say up to five words to the target before they act or make a decision.</p><h4>New Opportunities</h4><p>(op): If you target another character and you succeed, you may perform an action immediately before the target performs their new action.</p><h4>Magnitude</h4><p><strong>Magnitude 1+:</strong> You see one possible consequence of the original action or decision that would occur before the end of the scene.</p><p><strong>Magnitude 2+:</strong> You see one additional possible consequence of the original action or decision that would occur in the next year.</p><p><strong>Magnitude 3+:</strong> You see one additional possible consequence of the original action or decision that would occur in the next decades, or even further in the future.</p>","source":{"book":"celestial_realms","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-inversions-l5r-sortilege.Item.2AUf2kuJdMWvY13L","skill":"theology"},{"name":"Divination","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"ritual","rank":1,"description":"<p><span class=\"fontstyle0\">The ritualist peers into a character’s future, ascertaining their fate from the patterns of the stars, the char marks upon animal bones, the placement of cast shells, or other omens they can read.</span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a downtime activity, you may make a </span><span class=\"fontstyle2\">TN 2 Theology (void) check </span><span class=\"fontstyle3\">targeting one character to see glimpses of their future.</span></p><p><span class=\"fontstyle0\"><strong>Effects:</strong> </span><span class=\"fontstyle2\">If you succeed, choose one of the following omens that you see in the target’s near future:</span></p><ul><li><p><span class=\"fontstyle0\">- Omen of the Azure Dragon: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Artisan skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Black Tortoise: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Scholar skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the White Tiger: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Martial skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Vermilion Bird: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Social skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li><li><p><span class=\"fontstyle0\">- Omen of the Weaver and the Cowherd: </span><span class=\"fontstyle2\">The next time the target performs a check using a skill from the Trade skill group this game session, the target adds a kept (ring) set to an (op)(st) result.</span></p></li></ul><p><span class=\"fontstyle2\">If you fail, the GM chooses one of the above omens instead. The target cannot receive another divination until the next game session.</span></p><h4><span class=\"fontstyle5\">New Opportunities</span></h4><p><span class=\"fontstyle4\">(op)</span><span class=\"fontstyle0\">: </span><span class=\"fontstyle2\">If you fail, an additional omen appears to you after the first. Choose one of the above omens in addition to the one the GM chose.</span></p>","source":{"book":"core_rulebook","page":212},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.JUOu5wKW90qDj9BG","skill":"theology"},{"name":"All in Jest","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<p><span class=\"fontstyle0\"><em>Veteran courtiers sometimes play off missteps as jokes. This underhanded but effective tactic puts the other person in a difficult position: press the issue and seem stubborn, or let it slide and give the courtier a pass.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">When you make a Commerce (water), Courtesy (water), or Performance (water) check, you may spend (op) in the following way:</span></p><p><span class=\"fontstyle2\">(water)(op)+: </span><span class=\"fontstyle3\">If you forfeited honor as part of the check in order to say something rude or appeal to your target’s base desires (greed, lust, laziness, etc.), regain 1 honor per (op) spent this way (see </span><span class=\"fontstyle2\">Forfeiting Social Attributes</span><span class=\"fontstyle3\">, on page 37).</span></p>","source":{"book":"core_rulebook","page":220},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.vzyZwVERv5Q2kulT","skill":"commerce,courtesy,performance"},{"name":"Way of the Void","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When you make a check using your Void Ring, after rolling dice, you may receive a number of fatigue up to your school rank. If you do, you may </span><span class=\"fontstyle2\"><strong>pull</strong> </span><span class=\"fontstyle0\">or </span><span class=\"fontstyle2\"><strong>push</strong></span><span class=\"fontstyle0\">: </span></p><p><span class=\"fontstyle0\">If you </span><span class=\"fontstyle2\"><strong>pull</strong></span><span class=\"fontstyle0\">, choose a number of dice with non-blank results equal to the fatigue you received, and alter each to a blank result.</span></p><p><span class=\"fontstyle0\">If you </span><span class=\"fontstyle2\"><strong>push</strong></span><span class=\"fontstyle0\">, choose a number of dice with blank results equal to the fatigue you received, and alter each to a non-blank result of your choice.</span> </p>","source":{"book":"celestial_realms","page":82},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.fwNLwyKgWpWlq9nd"},{"name":"Wisdom of Countless Lifetimes","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"title_ability","rank":1,"description":"<p><span class=\"fontstyle0\">When making a skill check, you may spend 1 Void point to treat your skill rank as 1 higher, to a maximum of 6. If you fail the check, gain 1 Void point.</span></p>","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.1jgC3c1A3Dkvpb6k"},{"name":"One Within the Void","xp_used":6,"xp_cost":6,"in_curriculum":true,"bought_at_rank":1,"kind":"inversion","rank":1,"description":"<p><em>Within the emptiness of the Void, the divisions between “self” and “other” become as mutable as any other barriers that seem absolute within reality. Those trained to wield the Void can share their expertise, tendencies, and even emotional states with other beings, allowing them to act with uncanny coordination.</em></p><p><strong>Activation:</strong> As a Support action, you may make a TN 2 Sentiment (void) check targeting yourself and one other character at range 0–3.</p><p><strong>Effects:</strong> If you succeed, you augment all targets with the ability to communicate with each other without words, making their intentions clear even if they do not speak the same language. When any target makes a check, one other target may receive 2 fatigue to provide assistance on the check regardless of distance. This effect lasts until the end of the scene.</p><h4>New Opportunities</h4><p>(op)+: Choose one additional target per (op) spent this way.</p><h4>Magnitude</h4><p><strong>Magnitude 1+:</strong> When a target is dealt strife, one other target of your choice may receive that strife instead.</p><p><strong>Magnitude 3+:</strong> Choose a ring or skill. When any target makes a check using that ring or skill, they may use any other target’s rank in that ring or skill instead of their own.</p>","source":{"book":"celestial_realms","page":114},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-inversions-l5r-sortilege.Item.0XWS8RHp15XFc5Ji","skill":"sentiment"},{"name":"Nature’s Touch","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"invocation","rank":1,"description":"<p>Shinjo's Whispers (Ancestral), Run Alongside the Ki-Rin (Fortunist), Voice of the Glen King (Foreign)</p><p><em>To perform this rite, the shugenja seeks Chikushō-dō, the Realm of Animals, in the world around them and in their own heart. This allows the shugenja to communicate with (though not dominate) animals of the mortal realm.</em></p><p><strong>Activation:</strong> As a Support action, you may make a TN 1 Theology (air) check targeting yourself.</p><p><strong>Effects:</strong> If you succeed, you augment yourself with the ability to speak to animals of the natural world (but not Otherworldly or Tainted beings). Animals can understand you (within their ability to do so, naturally—human political relationships will have no meaning to horses, no matter how many times you explain them). They are not compelled to obey you, however. This effect persists until the end of the scene.</p><h4>New Opportunities</h4><p>(air)(op): Until the end of the scene, you can understand animals’ speech.</p><p>(air)(op): If you succeed, the animal also acts favorably toward you automatically due to your politeness, fulfilling one request that does not put it in danger without having to be convinced with bribes of food or subsequent checks.</p><p>(air)(op)(op): If you succeed, you can communicate with an Otherworldly being this way, provided it has anything to say to you.</p>","source":{"book":"core_rulebook","page":194},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.RGv4DW5lszwSVJiy","skill":"theology"},{"name":"Tea Ceremony","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ritual","rank":2,"description":"<p><span class=\"fontstyle0\"><em>When Lady Doji served tea for the very first Emperor, the tea ceremony was born. Ceremony styles vary among the clans, from the gilded tea rooms of the Phoenix to the imperfect tea bowls of the Dragon, the early morning gatherings of the Crane to the snow- and moon-viewing ceremonies of the Scorpion. However, at its core the tea ceremony is fundamentally an appreciation of tea and, if done well, a spiritual moment for its participants. The tea represents all five elements: the fire used to heat the water, the earth from which the tea is grown, and the air that carries the aroma of the tea. Finally, void holds all four elements together, and brings in the mysterious fifth element, the moment of harmony and tranquility as one sips the tea.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">Once per game session, as a downtime activity using a tea set, you may make a </span><span class=\"fontstyle2\">TN 2 Performance (void) check </span><span class=\"fontstyle3\">targeting yourself and a number of other characters up to your ranks in Culture, who are also participants. Up to one other participant may assist, providing the usual benefits (see </span><span class=\"fontstyle2\">Assistance </span><span class=\"fontstyle3\">on page 26).</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">Each target removes 3 strife, plus additional strife equal to your bonus successes.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle2\">: </span><span class=\"fontstyle3\">Reduce the TN of each target’s next check by 1.</span></p><p><span class=\"fontstyle5\">(op)</span><span class=\"fontstyle6\">+: </span><span class=\"fontstyle3\">Each target removes 1 fatigue, plus 1 fatigue per (op)</span><span class=\"fontstyle5\">(op) </span><span class=\"fontstyle3\">spent this way.</span></p><p><span class=\"fontstyle5\">(op)(op)</span><span class=\"fontstyle6\">: </span><span class=\"fontstyle3\">If you succeed, each target gains 1 Void point.</span></p>","source":{"book":"core_rulebook","page":213},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.JWmEEgfShNBM4fEK","skill":"performance"},{"name":"All Arts Are One","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<p><span class=\"fontstyle0\"><em>Just as the four elements are bound together by Void, certain underlying principles, including aesthetics, logic, and discipline, unite all forms of art. By meditating on these similarities, a courtier is able to more easily grasp the fundamentals of any subject.</em></span></p><p><span class=\"fontstyle2\"><strong>Activation:</strong> </span><span class=\"fontstyle3\">As a Support action, you may make a </span><span class=\"fontstyle2\">TN 4 Martial skill (void)</span><span class=\"fontstyle3\">, </span><span class=\"fontstyle2\">Games (void)</span><span class=\"fontstyle3\">, or </span><span class=\"fontstyle2\">Performance (void) check </span><span class=\"fontstyle3\">to rapidly absorb information on a new activity covered by that skill.</span></p><p><span class=\"fontstyle2\"><strong>Effects:</strong> </span><span class=\"fontstyle3\">If you succeed, you immediately intuit how to wield a new weapon, play a new game, use a new instrument, or perform a new song, dance, or other task. You do not apply any TN increase that might be associated with dealing with something new to you.</span></p><h4><span class=\"fontstyle4\">New Opportunities</span></h4><p><span class=\"fontstyle2\">(void)(op): </span><span class=\"fontstyle3\">Choose a ring. Reduce the TN of your next check using that ring for the chosen skill by 1. This effect persists until the end of your next turn (or until the end of the scene during a narrative scene).</span></p>","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.eh6kYhfLx1lOwBZV","skill":"martial,games,performance"},{"name":"Fires of Purity","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"invocation","rank":2,"description":"<p>Balm of Licking Flames (Alchemy), Cast in Emma-Ō’s Lantern (Fortunist), Coat of the Flame Djinn (Foreign)</p><p><em>Their eyes glowing, the shugenja finishes the gestures and chants and unleashes fire around them. These flames swirl from the shugenja’s hands and cling to their body, and withering heat blasts anyone else nearby.</em></p><p><strong>Activation:</strong> As a Support action, you may make a TN 2 Theology (fire) check targeting one character at range 0–3.</p><p><strong>Effects:</strong> If you succeed, you augment the target with sacred fire. A number of range bands around the target equal to your Fire Ring count as Dangerous terrain for any character other than the target (see Terrain, on page 267 of the core rulebook). This effect persists for one round, plus additional rounds equal to your bonus successes.</p><h4>New Opportunities</h4><p>(fire)(op): If you succeed, the target also gains resistance equal to your Fire Ring against physical and supernatural fire.</p><p>(fire)(op): While this effect persists, your target’s weapons count as having the Sacred item quality.</p><p>(fire)(op)(op): This effect persists until the end of the scene instead.</p>","source":{"book":"celestial_realms","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-invocations-l5r-sortilege.Item.QhYBuXKTcSQjrggx","skill":"theology"},{"name":"The Lotus Blooms","xp_used":6,"xp_cost":6,"in_curriculum":true,"bought_at_rank":2,"kind":"inversion","rank":2,"description":"<p><em>In the Void exist all possibilities, which become realities through choices—of humans, of animals, and even of celestial beings. Normally, the countless possibilities are invisible, and hints of them can only be glimpsed in moments of true clarity. However, a Void wielder can enlighten a character regarding the possible consequences of their future actions. This insight can be valuable, but as a thousand phantom worlds unfold before them, only a character with great clarity of purpose can possibly maintain their path.</em></p><p><strong>Activation:</strong> As a Scheme and Support action, you may make a TN 3 Theology (void) check targeting one character at range 0–1.</p><p><strong>Effects:</strong> If you succeed, you augment and curse your target. When your target makes a check, instead of keeping a number of dice up to the ring they used, they keep a number of dice up to their Void Ring (and must keep as many dice as possible within this limit). Your target does not receive strife for kept (st) results, but for each kept (st) result, your target receives 1 fatigue. If they become Incapacitated this way, your target also gains the Exhausted condition. This effect persists until the end of your target’s next turn.</p><h4>Magnitude</h4><p><strong>Magnitude 1–2:</strong> This effect persists for a number of additional rounds equal to the magnitude.</p><p><strong>Magnitude 3+:</strong> This effect persists until the end of the scene.</p>","source":{"book":"celestial_realms","page":117},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-inversions-l5r-sortilege.Item.ywvfDZOyqBipFxUj","skill":"theology"}],"peculiarities":[{"name":"Portentous Birth","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"fire","types":"Interpersonal, Spiritual","description":"<p><span class=\"fontstyle0\"><em>The childbirth assistant carried the silent bundle to the priest outside of the birthing chamber. The child’s grandmother followed with a stony look on her face.</em></span></p><p><span class=\"fontstyle2\"><em>Why isn’t the child crying? </em></span><span class=\"fontstyle0\"><em>the priest thought.</em></span></p><p><span class=\"fontstyle0\"><em>“Show him,” the grandmother said.</em></span></p><p><span class=\"fontstyle0\"><em>The assistant carefully unwrapped the bundle. The unnerving infant stared about, clear-eyed, as the grandmother pointed out the seven moles in a perfect circle on their ear.</em></span></p><p><span class=\"fontstyle0\"><em>“The child will reverse the family’s bad fortune!” the priest exclaimed. The grandmother let out a breath and smiled for the first time in years.</em></span></p><p></p><p><span class=\"fontstyle2\">The following apply to a character with the Portentous Birth distinction:</span></p><ul><li><p><span class=\"fontstyle2\">- You are known among your clan or family group to have been born under blessed circumstances or have had some sort of mark or other indication of greatness bestowed upon you by the Heavens. When you interact with someone who knows of your portentous birth and believes in its power, they treat you favorably and may be inclined to give you special privileges as long as you do not give them a reason to treat you otherwise.</span></p></li><li><p><span class=\"fontstyle2\">- When performing a check for which your fortuitous birth is an asset (such as a Composition (fire) check to craft a clever request to someone who believes in the legacy of your birth or a Theology (fire) check to theorize about an omen), you may reroll up to two dice.</span></p></li></ul>","source":{"book":"celestial_realms","page":89},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.US7uSaPQHxj4wCKy"},{"name":"Adopted Peasant","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"fire","types":"Interpersonal","description":"<p><em>Even though she sat with the rest of her adopted family, she had never felt so invisible.</em></p><p><em>“This is why we sweep the shrine of dirt. Any foreign intrusion violates its sanctity,” her brother said.</em></p><p><em>Takako bowed her head ever so slightly. “Yes, but priests also sprinkle salt in the corners. So a foreign intrusion can sometimes strengthen its purity.”</em></p><p><em>Her brother tensed up. The rest of her family refused to look at her. This transgression will not be forgotten.</em></p><p></p><p>The following apply to a character with the Adopted Peasant adversity:</p><ul><li><p>- Although adopted by a samurai family, you were born a peasant. Other samurai who know this fact are likely to look down upon you and may use this fact against you socially.</p></li><li><p>- When you make a check to deal authoritatively or collegially with a samurai who knows of your peasant birth (such as a Command (fire) check to give an order to a subordinate or a Courtesy (fire) check to impugn another’s honor), you must choose and reroll two dice showing (su) or (ex) results. After resolving the check, if you failed, you regain 1 Void point.</p></li></ul>","source":{"book":"emerald_empire","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.2bPrBcyXEsRvGPnn"},{"name":"Generosity","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"water","types":"Interpersonal","description":"<p><span class=\"fontstyle0\"><em>During the sixth month of the year after the biannual collection of taxes, the city of Ryokō Owari Toshi celebrates the Days of Generosity. As the festival begins, the head priest of the local temple draws a name in a lottery. The person whose name is drawn becomes “King of Generosity” and “rules” over the festival.</em></span></p><p><span class=\"fontstyle0\"><em>The festival is marked by gift giving and drunkenness. The festival king decides who the best gift giver is on each of the celebration’s three days. That person receives a portion of the “king’s purse,” a collection of coins given to the festival king to pay him for blessing the giver with a prosperous year ahead.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Generosity passion:</span></p><ul><li><p><span class=\"fontstyle3\">- You can always identify a proper gift for a particular person that does not risk giving offense or slighting them publicly.</span></p></li><li><p><span class=\"fontstyle3\">- After performing a check to acquire or give a gift (such as a Design (water) check to select an item that complements someone’s wardrobe or a Commerce (water) check to find and select a gift at a market), you remove 3 strife.</span></p></li></ul>","source":{"book":"core_rulebook","page":113},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.bvb90GLa9nJkkUun"},{"name":"Loneliness","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"void","types":"Interpersonal, Mental","description":"<p><em>A stalk of barley,<br>Plucked by a starving farmer,<br>Quickly forgotten.</em></p><p><strong>Effects:</strong> The following apply to a character with the Loneliness anxiety:</p><ul><li><p>- You derive energy and pleasure from social interactions, and being alone makes you uncomfortable or morose. You look for excuses to avoid being alone and find it difficult to turn down any social engagement.</p></li><li><p>- After performing a check that requires you to be alone (such as a Composition (void) check to write a letter declining an invitation to the theater or a Meditation (void) check to spend a prolonged time in dedicated introspection), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</p></li></ul>","source":{"book":"emerald_empire","page":248},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.yc64FF9SMsQEjs4R"},{"name":"Support of Brotherhood of Shinsei","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"water","types":"Interpersonal","custom":true,"description":"<p><span class=\"fontstyle0\"><em>Akodo Emi avoided the rōnin’s stroke narrowly, sweeping at his feet to gain distance. He was good, yet she could beat him. But not quickly, and time was her true enemy tonight.</em></span></p><p><span class=\"fontstyle0\"><em>Suddenly, a hail of slingstones clattered across the ground near the rōnin’s feet. Down the street rushed several figures wearing the Mon of the Sparrow.</em></span></p><p></p><p><span class=\"fontstyle3\">The following apply to a character with the Support of [One Group] distinction:</span></p><ul><li><p><span class=\"fontstyle3\">- You have proven yourself to a particular group, which is willing to help you when doing so will not damage its reputation. Its members will offer you their hospitality, including meals, a place to rest, and medical attention if they have a healer. They will also grant you access to their other facilities, such as libraries, smithies, or stables. Confer with the GM to select a campaign-appropriate group when choosing this advantage.</span></p></li><li><p><span class=\"fontstyle3\">- When performing a check to interact with the members of the chosen group that relies on your rapport (such as a Command (water) check to issue them orders or a Performance (water) check to cause an audience of them to desire something), you may reroll up to two dice.</span></p></li></ul>","source_reference":{"source":"core_rulebook","page":110}}],"titles":[{"name":"Awakened Soul","xp_used":44,"xp_cost":44,"in_curriculum":false,"bought_at_rank":1,"description":"<p><span class=\"fontstyle0\">Most Rokugani believe in reincarnation, the passage of the soul into a new form after the death of the body. Shinseism in particular emphasizes the importance of reincarnation and the role it plays within the cosmology, but even among those who favor other religious traditions, few argue that existence ends at death. While the specifics of how and why reincarnation occurs vary by doctrine, most religious accounts agree that memory is erased upon death, in the afterlife, or during the process of the return to life.</span></p><p><span class=\"fontstyle0\">Yet some things can persist even across lifetimes. Some people are capable of connecting with the lives of past people, entities, and existences as an extension of their own being - beings that by all account seem to be their past lives. The Togashi Tattooed Order is one organization dedicated to those who again and again reincarnate and seek a particular destiny, but other spiritualists claim to have memories of their past lives as well, and the phenomenon can occur within individuals unrelated to any religious group.</span></p><p><span class=\"fontstyle0\">Memories of one's past lives generally begin murky, but may become clearer in physical proximity to individuals, artifacts, or places important to those beings. These visions and senses can be terrifying and disorienting at first, but when they occur, it is often of vital importance to both past and present self. Indeed, some work cannot be completed in a single lifetime.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">The GM. Even more than usual, this title is only available if it is narratively appropriate to the campaign.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+0</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Wisdom of Countless Lifetimes</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Social Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Scholar Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Culture</p></td><td><p>Skill</p></td></tr><tr><td><p>Meditation</p></td><td><p>Skill</p></td></tr><tr><td><p>Survival</p></td><td><p>Skill</p></td></tr><tr><td><p>Theology</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-kiho.Item.L5RCoreKih000038\" data-pack=\"l5r5e.core-techniques-kiho\" data-type=\"Item\" data-id=\"L5RCoreKih000038\">(kiho) Eternal Mind’s Gate</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-rituals.Item.L5RCoreRit000035\" data-pack=\"l5r5e.core-techniques-rituals\" data-type=\"Item\" data-id=\"L5RCoreRit000035\">(ritual) Trance of Lives Past</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source":{"book":"writ_of_the_wild","page":142},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.lwnOHnIHVy5M9wUb"}],"bonds":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p><span class=\"fontstyle0\">Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</span></p>","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Bō","quantity":1,"description":"<p><span class=\"fontstyle0\">The bō, a humble staff, is a versatile weapon found throughout Rokugan. Roughly six feet long and made from sturdy hardwood, it is carried by travelers who need both a walking stick and an inconspicuous weapon.</span></p>","source":{"book":"core_rulebook","page":235},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.0ZcXEpZP8WC9KVUv","damage":6,"deadliness":2,"range":"1-2","grip_1":"N/A","skill":"melee","category":"Polearms","rarity":"2","zeni":"2 bu","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Sanctified Robes","quantity":1,"description":"<p><span class=\"fontstyle0\">The vestments of shugenja, shrine keepers, and other religious figures are blessed by kami and thus grant mystical protection. Traditionally, such robes consist of a white garment called </span><span class=\"fontstyle2\">jōe </span><span class=\"fontstyle0\">(literally, “pure cloth”) and a peaked hat, but they can be simpler, such as a white haori top and red hakama bottoms, or even an elaborate kimono.</span></p>","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.Cq1koK56k9dvLfMh","armor":{"physical":1,"supernatural":3},"rarity":"7","zeni":"4 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Scroll satchel","quantity":1,"description":"","source":{"book":"core_rulebook","page":60},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.DhMU7Z6UsxB7CSvR","rarity":"3","zeni":"1 bu"},{"name":"Traveling pack","quantity":1,"description":"<p><span class=\"fontstyle0\">Blanket, bowl, chopsticks, four days of travel rations, flint and tinder, and any three other items of the player’s choice that are rarity 4 or lower.</span></p>","source":{"book":"core_rulebook","page":245},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.Rex7fGo6R1KuUhQJ","rarity":"1","zeni":"10 koku","properties":[{"id":"L5RCorePro000012","name":"Mundane"}]},{"name":"Hana [Doll]","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Finger of Jade","quantity":1,"description":"<p>A finger of jade is a length of the precious green stone worn about the neck on a thong to ward off the corrupting effects of the Taint. Bit by bit, the finger of jade is consumed by this process. (Cost: 1 koku. Rarity: 6. Qualities: Sacred.)</p>","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.DPc5XLaPHWGkcNs5","rarity":"6","zeni":"1 koku","properties":[{"id":"L5RCorePro000014","name":"Sacred"}]}]}]};
